ALTER TABLE user_account ADD COLUMN deleted_at DATETIME(3) NULL;
ALTER TABLE user_account ADD COLUMN version BIGINT NOT NULL DEFAULT 1;
ALTER TABLE user_account ADD COLUMN auth_version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE `role` ADD COLUMN role_kind VARCHAR(10) NOT NULL DEFAULT 'IDENTITY';
ALTER TABLE `role` ADD COLUMN level_code VARCHAR(20) NULL;
ALTER TABLE `role` ADD COLUMN owner_province_org_id BIGINT NULL;
ALTER TABLE `role` ADD COLUMN system_protected BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE `role` ADD COLUMN version BIGINT NOT NULL DEFAULT 1;
ALTER TABLE `role` ADD COLUMN deleted_at DATETIME(3) NULL;
UPDATE `role` SET level_code = code WHERE role_kind = 'IDENTITY';
ALTER TABLE `role` ADD CONSTRAINT fk_role_owner_province FOREIGN KEY (owner_province_org_id) REFERENCES org_unit(id);
INSERT INTO `role` (id,code,name,role_kind,level_code,system_protected) VALUES (4,'PROVINCE_DEFAULT','省级默认功能角色','FUNCTION','PROVINCE',TRUE),(5,'CITY_DEFAULT','市级默认功能角色','FUNCTION','CITY',TRUE),(6,'ENTERPRISE_DEFAULT','企业默认功能角色','FUNCTION','ENTERPRISE',TRUE);
CREATE TABLE permission (code VARCHAR(80) PRIMARY KEY, name VARCHAR(80) NOT NULL, level_code VARCHAR(20) NOT NULL, feature VARCHAR(80) NOT NULL, operation VARCHAR(80) NOT NULL);
CREATE TABLE role_permission (role_id BIGINT NOT NULL, permission_code VARCHAR(80) NOT NULL, PRIMARY KEY(role_id,permission_code), CONSTRAINT fk_role_permission_role FOREIGN KEY(role_id) REFERENCES `role`(id), CONSTRAINT fk_role_permission_permission FOREIGN KEY(permission_code) REFERENCES permission(code));
CREATE TABLE permission_route (http_method VARCHAR(8) NOT NULL, path_pattern VARCHAR(200) NOT NULL, identity_code VARCHAR(20) NOT NULL, permission_code VARCHAR(80) NOT NULL, PRIMARY KEY(http_method,path_pattern,identity_code), CONSTRAINT fk_route_permission FOREIGN KEY(permission_code) REFERENCES permission(code));
CREATE TABLE admin_audit_event (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_user_id BIGINT NOT NULL, action VARCHAR(40) NOT NULL, target_user_id BIGINT NULL, target_role_id BIGINT NULL, event_at DATETIME(3) NOT NULL, CONSTRAINT fk_admin_audit_actor FOREIGN KEY(actor_user_id) REFERENCES user_account(id), CONSTRAINT fk_admin_audit_user FOREIGN KEY(target_user_id) REFERENCES user_account(id), CONSTRAINT fk_admin_audit_role FOREIGN KEY(target_role_id) REFERENCES `role`(id));
INSERT INTO id_allocator SELECT 'role', GREATEST(COALESCE(MAX(id),0)+1,1000) FROM `role`;
