INSERT INTO role_permission (role_id,permission_code) SELECT CASE level_code WHEN 'PROVINCE' THEN 4 WHEN 'CITY' THEN 5 ELSE 6 END, code FROM permission;
INSERT INTO user_role (user_id,role_id) SELECT u.id,CASE o.org_type WHEN 'PROVINCE' THEN 4 WHEN 'CITY' THEN 5 ELSE 6 END FROM user_account u JOIN org_unit o ON o.id=u.org_id WHERE o.org_type IN ('PROVINCE','CITY','ENTERPRISE');
